\title{Plateaus in Rank Correlation:\\ A Sharp Cubic Law for Locally Starved Rankings}
\author{Aristotle}
\date{September 3, 2026}

\begin{document}
\maketitle

\begin{abstract}
We give an exact combinatorial explanation for a phenomenon observed in the empirical
evaluation of ranking heuristics: as instances grow, the Spearman rank correlation between a
cheap ``dial'' statistic and an expensive target degrades, but the degradation \emph{stops} at
a strictly positive level rather than continuing to zero. Our starting point is an exact
reversal duality $3D(f)+3D(\bar f)=n^3-n$ relating the squared rank displacement
$D(f)=\sum_i (i-f(i))^2$ of a ranking $f$ of $\{0,\dots,n-1\}$ to that of its mirror
$\bar f(i)=n-1-f(i)$. Duality yields the sharp extremal bound $3D(f)\le n^3-n$ together with the
identification of its unique extremiser, hence $-1\le\rho\le1$ for
$\rho(f)=1-6D(f)/(n^3-n)$. Modelling degradation as \emph{local starvation} --- the ranking is
exact outside a window of $m$ consecutive ranks and arbitrary inside it --- a block transfer
principle gives $3D(f)\le m^3-m$ \emph{independently of $n$}, whence the plateau floor
$\rho\ge 1-2\alpha^3$ with $\alpha=m/n$, uniformly in $n$; the floor is strictly positive
exactly when $\alpha<2^{-1/3}\approx0.7937$. The bound is attained: the worst window ranking
has closed form $\rho=1-2(m^3-m)/(n^3-n)$, obeys $|\rho-(1-2\alpha^3)|\le 2/(n^2-1)$, is
strictly decreasing in window width, changes sign exactly at $2(m^3-m)=n^3-n$, and converges to
$1-2\alpha^3$ along families of fixed shape. In the starved-everywhere regime --- the ranks cut
into $k$ segments, each internally scrambled, coarse order between segments retained --- we
prove $\rho\ge 1-2/k^2$ independently of segment length, so $\rho\ge 1/2$ already for $k\ge2$.
Calibrating to an observed reading of $0.437$ with interval $[0.393,0.480]$: a starved fraction
$\alpha=0.66$ predicts $1-2(0.66)^3=0.425008$, inside the interval; every instance with
$\alpha\le0.66$ scores at least $0.425$; and a rival starved on at least $0.69$ of its range is
beaten by at least $0.070$ for all $n\ge20$.
\end{abstract}

\noindent\textbf{Keywords:} Spearman rank correlation; squared rank displacement; extremal
permutation problems; block-localised permutations; plateau phenomena; cubic scaling laws.

\section{Introduction}

\subsection{The empirical puzzle}

One has a \emph{target} quantity that is expensive to compute for each of $n$ objects, and a
\emph{dial}: a cheap statistic whose ordering one hopes correlates with the target's ordering.
The quality of the dial is measured by Spearman's rank correlation coefficient.

In the study motivating this work, a dial $T$ was evaluated against a target rate statistic at
increasing problem sizes (parameterised by a bit length). The correlation declined with size,
and the natural extrapolation was $\rho\to0$. Instead, at bit length $60$ the reading was
\[
\rho(T,\text{rate})=0.437,\qquad \text{interval } [0.393,\,0.480],
\]
and it did not move further; the dial also retained a stable advantage of about $+0.070$ over a
simpler competing dial. Two hypotheses failed: \textbf{H1} (monotone continuation of the
degradation to zero) and \textbf{H3} (recovery at larger sizes). The regime was \emph{starved}:
only about $0.89\%$ of items possessed the property the dial tracks, so local discrimination was
almost entirely absent. This paper supplies an exact mechanism producing such a plateau and
proves that within it both H1 and H3 must fail.

\subsection{The mechanism in one sentence}

Squared rank displacement is a \emph{cubic} resource: $n$ ranks express at most $(n^3-n)/3$
units of disagreement, while damage confined to a window of $m$ ranks consumes at most
$(m^3-m)/3$. The ratio is $\alpha^3$ with $\alpha=m/n$, so the correlation depends only on the
\emph{shape} of the damage, not the size of the instance --- and a quantity depending only on a
shape parameter that has stopped changing is, by definition, a plateau.

\section{Rank displacement and the reversal duality}

\begin{definition}[Rank permutation]
A map $f:\mathbb{N}\to\mathbb{N}$ is a \emph{rank permutation of $\{0,\dots,n-1\}$} if
$f(i)<n$ for all $i<n$ and $f$ is injective on $\{0,\dots,n-1\}$; equivalently $f$ maps
$\{0,\dots,n-1\}$ bijectively onto itself. Interpretation: the object of true rank $i$ receives
dial rank $f(i)$.
\end{definition}

\begin{definition}[Squared displacement and Spearman coefficient]
$D_n(f)=\sum_{i=0}^{n-1}(i-f(i))^2$, and for $n\ge2$,
$\rho_n(f)=1-\dfrac{6D_n(f)}{n^3-n}$.
\end{definition}

We use the elementary power sums
\begin{equation}\label{eq:powersums}
2\sum_{i=0}^{n-1} i=n^2-n,\qquad 6\sum_{i=0}^{n-1} i^2=2n^3-3n^2+n .
\end{equation}
Expanding the square and using $\sum_i f(i)^2=\sum_i i^2$ gives the inner-product form
\begin{equation}\label{eq:inner}
D_n(f)=2\sum_{i<n}i^2-2\sum_{i<n} i\,f(i),
\end{equation}
whence $\sum_i i f(i)\le\sum_i i^2$ for every rank permutation (a Cauchy--Schwarz statement
obtained for free from $D_n(f)\ge0$).

\begin{definition}[Mirror]
The \emph{mirror} of a rank permutation $f$ of $\{0,\dots,n-1\}$ is $\bar f(i)=n-1-f(i)$; it is
again a rank permutation.
\end{definition}

\begin{theorem}[Reversal duality]\label{thm:duality}
For every rank permutation $f$ of $\{0,\dots,n-1\}$,
\[
3D_n(f)+3D_n(\bar f)=n^3-n,
\]
equivalently $\rho_n(f)+\rho_n(\bar f)=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply \eqref{eq:inner} to $f$ and to $\bar f$. With $S_1=\sum_{i<n}i$, $S_2=\sum_{i<n}i^2$,
\[
\sum_{i<n} i\,\bar f(i)=\sum_{i<n} i\,(n-1-f(i))=(n-1)S_1-\sum_{i<n} i f(i),
\]
so the unknown cross term cancels when the two copies of \eqref{eq:inner} are added, leaving
$4S_2-2(n-1)S_1$. Substituting \eqref{eq:powersums} gives $(n^3-n)/3$; multiply by $3$.
\end{proof}

The identity is exact for \emph{every} permutation, with no error term.

\begin{theorem}[Sharp extremal bound]\label{thm:extremal}
For every rank permutation $f$ of $\{0,\dots,n-1\}$ we have $3D_n(f)\le n^3-n$, i.e.
$\rho_n(f)\ge-1$.
\end{theorem}

\begin{proof}
$D_n(\bar f)\ge0$ is a sum of squares; subtract it from Theorem~\ref{thm:duality}.
\end{proof}

With $D_n(f)\ge0$ this pins the range of $\rho_n$ to $[-1,1]$, and $\rho_n(\id)=1$.

\begin{theorem}[Unique extremiser]\label{thm:unique}
Let $\rev_n(i)=n-1-i$. Then $3D_n(\rev_n)=n^3-n$ exactly, so $\rho_n(\rev_n)=-1$; conversely if
a rank permutation $f$ satisfies $3D_n(f)=n^3-n$ then $f(i)=n-1-i$ for all $i<n$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:duality} to $f=\id$, whose displacement is $0$ and whose mirror is
$\rev_n$. For uniqueness, equality in Theorem~\ref{thm:extremal} forces $D_n(\bar f)=0$, and
$D_n(g)=0$ iff $g$ fixes every rank below $n$; hence $n-1-f(i)=i$.
\end{proof}

We call $B(n)=(n^3-n)/3$ the \emph{displacement budget} of $n$ ranks. Its first values
$B(0),\dots,B(7)=0,0,2,8,20,40,70,112$ agree with exhaustive enumeration over all permutations
of up to seven elements; for instance the reversal of seven items has displacement
$6^2+4^2+2^2+0+2^2+4^2+6^2=112$.

\section{Local starvation: block-localised rankings}

\begin{definition}[Block-localised ranking]\label{def:block}
Let $a+m\le n$. A map $f$ is \emph{block-localised in the window $[a,a+m)$} if
(i) $f(i)=i$ for every $i<a$ and every $i\ge a+m$; and
(ii) $f$ maps $[a,a+m)$ into itself with $j\mapsto f(a+j)-a$ a rank permutation of
$\{0,\dots,m-1\}$.
\end{definition}

Such an $f$ is automatically a rank permutation of $\{0,\dots,n-1\}$: it models a dial that has
retained all coarse ordering information but lost all discrimination inside a band of relative
width $\alpha=m/n$.

\begin{theorem}[Block transfer]\label{thm:transfer}
If $f$ is block-localised in $[a,a+m)$ then $D_n(f)=D_m\bigl(j\mapsto f(a+j)-a\bigr)$.
\end{theorem}

\begin{proof}[Proof sketch]
Every rank outside the window contributes $(i-f(i))^2=0$. Restricting the sum to $[a,a+m)$ and
reindexing $i=a+j$, the displacement $i-f(i)$ equals $j-(f(a+j)-a)$.
\end{proof}

\begin{theorem}[Size-free damage bound]\label{thm:sizefree}
If $f$ is block-localised in a window of width $m$ inside $n$ ranks then $3D_n(f)\le m^3-m$, a
bound independent of $n$.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:transfer} with Theorem~\ref{thm:extremal} applied on $m$ ranks.
\end{proof}

\begin{definition}[Worst window ranking]
The \emph{block reversal} $R_{a,m}$ is the identity outside $[a,a+m)$ and reverses the window:
$R_{a,m}(i)=a+(m-1-(i-a))$ for $a\le i<a+m$.
\end{definition}

\begin{proposition}\label{prop:blockrev}
$R_{a,m}$ is block-localised in $[a,a+m)$ and attains Theorem~\ref{thm:sizefree} with equality:
$3D_n(R_{a,m})=m^3-m$.
\end{proposition}

\begin{proof}
By Theorem~\ref{thm:transfer} its displacement equals that of $\rev_m$, namely $(m^3-m)/3$ by
Theorem~\ref{thm:unique}.
\end{proof}

\section{The plateau floor}

\begin{lemma}[Cubic comparison]\label{lem:cubic}
If $1\le M\le\alpha N$ with $0\le\alpha\le1$ and $N\ge2$ (reals), then
$M^3-M\le\alpha^3(N^3-N)$.
\end{lemma}

\begin{proof}[Proof sketch]
$t\mapsto t^3-t$ is increasing for $t\ge1$ and $\alpha N\ge M\ge1$, so
$M^3-M\le(\alpha N)^3-\alpha N$. Since $0\le\alpha\le1$ we have $\alpha^3\le\alpha$, hence
$\alpha^3N\le\alpha N$ and $(\alpha N)^3-\alpha N\le\alpha^3N^3-\alpha^3N=\alpha^3(N^3-N)$.
\end{proof}

\begin{theorem}[Degradation floor, integral form]\label{thm:intfloor}
If $f$ is block-localised in a window of width $m$ inside $n\ge2$ ranks, then
\[
\rho_n(f)\ \ge\ 1-\frac{2(m^3-m)}{n^3-n}.
\]
\end{theorem}

\begin{theorem}[Plateau floor; main theorem]\label{thm:plateau}
Let $f$ be block-localised in a window of width $m\ge1$ inside $n\ge2$ ranks, and suppose the
window occupies at most a fraction $\alpha\in[0,1]$ of the ranks, i.e.\ $m\le\alpha n$. Then
\[
\rho_n(f)\ \ge\ 1-2\alpha^3
\]
uniformly in $n$.
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:cubic} with $M=m$, $N=n$ to the numerator of
Theorem~\ref{thm:intfloor}.
\end{proof}

\begin{corollary}[Strictly positive floor]\label{cor:pos}
Under the hypotheses of Theorem~\ref{thm:plateau}, if $2\alpha^3<1$ --- that is,
$\alpha<2^{-1/3}\approx0.7937$ --- then $\rho_n(f)>0$ for every $n$.
\end{corollary}

Theorem~\ref{thm:plateau} refutes H1 inside the model: for a fixed starved fraction below
$2^{-1/3}$ the correlation is bounded away from zero by an explicit constant, uniformly in the
instance size.

\section{The exact degradation curve}

\begin{theorem}[Closed form]\label{thm:closed}
For $a+m\le n$ and $n\ge2$, $\displaystyle \rho_n(R_{a,m})=1-\frac{2(m^3-m)}{n^3-n}$.
\end{theorem}

Thus Theorem~\ref{thm:intfloor} is an equality for the block reversal: the plateau level is
achieved by an explicit dial.

\begin{theorem}[Strict monotone degradation]\label{thm:mono}
If $1\le m<m'$ and $a+m'\le n$ with $n\ge2$, then $\rho_n(R_{a,m'})<\rho_n(R_{a,m})$.
\end{theorem}

\begin{proof}[Proof sketch]
$m'^3-m'-(m^3-m)=(m'-m)(m'^2+m'm+m^2-1)>0$ for $m\ge1$; divide by the fixed positive
denominator.
\end{proof}

Monotonicity in bit length is not a statement about a single permutation; monotonicity in
\emph{window width} is, and it is exactly true.

\begin{theorem}[Phase transition]\label{thm:phase}
For $a+m\le n$ and $n\ge2$: $\rho_n(R_{a,m})>0 \iff 2(m^3-m)<n^3-n$. Asymptotically the
threshold is $m/n\to2^{-1/3}\approx0.7937$.
\end{theorem}

\begin{theorem}[Shape law with explicit error]\label{thm:shape}
For $a+m\le n$, $n\ge2$ and $\alpha=m/n$,
\[
\bigl|\rho_n(R_{a,m})-(1-2\alpha^3)\bigr|\ \le\ \frac{2}{n^2-1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
A direct computation gives the exact discrepancy
\[
\rho_n(R_{a,m})-(1-2\alpha^3)=\frac{2m\,(n^2-m^2)}{n^2\,(n^3-n)},
\]
nonnegative since $m\le n$ (the exact reading always sits slightly above the shape law). For
the upper bound, $m\le n$ and $n^2-m^2\le n^2$ give numerator at most $2n^3$, while the
denominator equals $n^3(n^2-1)$.
\end{proof}

The error is $2\times10^{-4}$ at $n=100$ and $2\times10^{-6}$ at $n=1000$.

\begin{theorem}[Attainment]\label{thm:limit}
Fix integers $p\le q$ with $q\ge2$ and set $\alpha=p/q$. Along the family with $n=q(k+1)$ ranks
and window width $m=p(k+1)$,
\[
\lim_{k\to\infty}\rho_{q(k+1)}\bigl(R_{0,\,p(k+1)}\bigr)=1-2\alpha^3 .
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:shape} the discrepancy is at most $2/(n^2-1)\le 2/(k+1)\to0$, since
$n=q(k+1)\ge2(k+1)$.
\end{proof}

Hence the floor is an \emph{attained infimum}, which refutes H3: a quantity converging to its
infimum from above with error $\Theta(1/n^2)$ does not rebound.

