"""Algorithm 2: exhaustive extremal-displacement search and budget certification."""

from __future__ import annotations

import itertools
from fractions import Fraction
from typing import Dict, List, Sequence, Tuple


def squared_displacement(f: Sequence[int]) -> int:
    return sum((i - fi) ** 2 for i, fi in enumerate(f))


def displacement_budget(n: int) -> Fraction:
    """B(n) = (n^3 - n)/3, the conjectured (and proved) maximum of D."""
    return Fraction(n**3 - n, 3)


def extremal_search(m: int) -> Tuple[int, List[Tuple[int, ...]]]:
    """
    Brute-force maximiser of D over all m! permutations of {0,...,m-1}.
    Returns (max value, list of all maximisers). Complexity O(m! * m).
    """
    best = -1
    argmax: List[Tuple[int, ...]] = []
    for p in itertools.permutations(range(m)):
        d = squared_displacement(p)
        if d > best:
            best, argmax = d, [p]
        elif d == best:
            argmax.append(p)
    return best, argmax


def certify_budget(max_m: int = 8) -> Dict[int, Tuple[int, Fraction, bool, bool]]:
    """
    For m = 0..max_m, compare the brute-force maximum with B(m) and check that the
    unique maximiser is the order reversal i -> m-1-i.
    """
    report: Dict[int, Tuple[int, Fraction, bool, bool]] = {}
    for m in range(max_m + 1):
        best, argmax = extremal_search(m)
        budget = displacement_budget(m)
        matches = Fraction(best) == budget
        unique_reversal = len(argmax) == 1 and list(argmax[0]) == [m - 1 - i for i in range(m)]
        report[m] = (best, budget, matches, unique_reversal or m < 2)
    return report


if __name__ == "__main__":
    for m, (best, budget, ok, uniq) in certify_budget(8).items():
        print(f"m={m:>2}  max D={best:>4}  (m^3-m)/3={str(budget):>6}  "
              f"equal={ok}  unique reversal maximiser={uniq}")

"""Algorithm 3: plateau-curve evaluation and inverse shape-law calibration."""

from __future__ import annotations

from fractions import Fraction
from typing import List, NamedTuple, Tuple


class PlateauReading(NamedTuple):
    n: int
    m: int
    alpha: float
    exact_rho: float
    shape_law: float
    error: float
    error_bound: float


def worst_window_rho(n: int, m: int) -> Fraction:
    """Exact rho of the block reversal on a window of width m: 1 - 2(m^3-m)/(n^3-n)."""
    if not (0 <= m <= n) or n < 2:
        raise ValueError("need 0 <= m <= n and n >= 2")
    return Fraction(1) - Fraction(2 * (m**3 - m), n**3 - n)


def shape_law(alpha: float) -> float:
    """The size-free plateau law rho = 1 - 2 alpha^3."""
    return 1.0 - 2.0 * alpha**3


def reading(n: int, m: int) -> PlateauReading:
    """One row of the plateau table, with the certified error bound 2/(n^2-1)."""
    alpha = m / n
    exact = float(worst_window_rho(n, m))
    law = shape_law(alpha)
    return PlateauReading(n, m, alpha, exact, law, exact - law, 2.0 / (n * n - 1))


def invert_shape_law(rho: float) -> float:
    """Recover the starved fraction alpha = ((1 - rho)/2)^(1/3) from an observed rho."""
    if rho > 1.0:
        raise ValueError("rho cannot exceed 1")
    return ((1.0 - rho) / 2.0) ** (1.0 / 3.0)


def calibrate(rho: float, lo: float, hi: float) -> Tuple[float, float, float]:
    """
    Turn an observed correlation with an uncertainty interval [lo, hi] into a
    starved-fraction estimate with interval. The cube root compresses uncertainty.
    """
    return invert_shape_law(rho), invert_shape_law(hi), invert_shape_law(lo)


def positivity_threshold() -> float:
    """The critical starved fraction 2^(-1/3): above it the floor is no longer positive."""
    return 2.0 ** (-1.0 / 3.0)


def plateau_table(pairs: List[Tuple[int, int]]) -> List[PlateauReading]:
    return [reading(n, m) for n, m in pairs]


if __name__ == "__main__":
    for r in plateau_table([(10, 3), (10, 7), (60, 40), (100, 66), (1000, 660)]):
        print(f"n={r.n:>5} m={r.m:>4} a={r.alpha:.4f} rho={r.exact_rho:.6f} "
              f"law={r.shape_law:.6f} err={r.error:.2e} bound={r.error_bound:.2e}")
    est, blo, bhi = calibrate(0.437, 0.393, 0.480)
    print(f"\nobserved rho = 0.437 -> alpha = {est:.6f}, interval [{blo:.6f}, {bhi:.6f}]")
    print(f"phase transition at alpha = {positivity_threshold():.6f}")

"""Algorithm 4: fragmentation sampler and floor certification."""

from __future__ import annotations

import random
from fractions import Fraction
from typing import List, Sequence, Tuple


def spearman(f: Sequence[int]) -> float:
    n = len(f)
    d = sum((i - fi) ** 2 for i, fi in enumerate(f))
    return 1.0 - 6.0 * d / (n**3 - n)


def segment_scramble(k: int, m: int, rng: random.Random, reverse: bool = False) -> List[int]:
    """
    Build a ranking on n = k*m ranks that is arbitrary inside each of k segments of
    length m but preserves the coarse order between segments. O(km) time.
    """
    f: List[int] = []
    for j in range(k):
        inner = list(range(m))
        if reverse:
            inner.reverse()
        else:
            rng.shuffle(inner)
        f.extend(j * m + v for v in inner)
    return f


def fragmentation_floor(k: int) -> float:
    """The guaranteed floor 1 - 2/k^2, independent of the segment length."""
    return 1.0 - 2.0 / (k * k)


def extremal_fragmented_rho(k: int, m: int) -> Fraction:
    """Exact rho of the all-segments-reversed witness: 1 - 2k(m^3-m)/((km)^3-km)."""
    n = k * m
    return Fraction(1) - Fraction(2 * k * (m**3 - m), n**3 - n)


def certify_floor(k: int, m: int, samples: int, seed: int = 20261040) -> Tuple[float, float, bool]:
    """
    Sample `samples` random segment-wise scramblings and report
    (worst observed rho, floor, floor respected).
    """
    rng = random.Random(seed)
    worst = min(spearman(segment_scramble(k, m, rng)) for _ in range(samples))
    floor = fragmentation_floor(k)
    return worst, floor, worst >= floor - 1e-12


if __name__ == "__main__":
    for k in (2, 3, 5, 10):
        for m in (5, 50):
            worst, floor, ok = certify_floor(k, m, 200)
            wit = float(extremal_fragmented_rho(k, m))
            print(f"k={k:>3} m={m:>3}  floor={floor:.6f}  worst sampled={worst:.6f}  "
                  f"all-reversed witness={wit:.6f}  respected={ok}")
